#ifndef PRACTICA_PAQUETES_ENTREGA_H
#define PRACTICA_PAQUETES_ENTREGA_H

// Dominio: 0 <= unidades <= 12.
// Cero unidades: cero minutos. Si hay unidades: 3 + 2 * unidades.
int minutos_preparacion(int unidades);

#endif

#include <iostream>

int minutos_preparacion(int unidades) {
    if (unidades == 0) {
        return 0;
    }
    return 3 + 2 * unidades;
}

int main() {
    std::cout << minutos_preparacion(0) << ':'
              << minutos_preparacion(1) << ':'
              << minutos_preparacion(5);
    return 0;
}

