// Devuelve capacidad - ocupadas. No modifica ningún estado.
int plazas_libres(int capacidad, int ocupadas);

#endif

#include "sala/cupo.h"

int plazas_libres(int capacidad, int ocupadas) {
    return capacidad - ocupadas;
}

